-- Idempotency-Key attempt storage (Phase 8, issue #48).
--
-- Generated by `node scripts/gen-migration.mjs add_idempotency_key` from a real
-- diff, not hand-written.
--
-- (userId, key) is both the scope and the concurrency mechanism. Whichever
-- request wins the INSERT owns the attempt; everyone else reads the row and
-- either replays the stored response or is told one is in flight. There is no
-- in-memory lock anywhere, so this behaves identically across instances — the
-- same division of labour as §5.1's conditional slot claim.
--
-- The unique index is what makes `INSERT ... ON CONFLICT DO NOTHING` safe here,
-- and it is created in the same migration as the table so there is never a
-- window in which rows can be written without it. No foreign key on userId:
-- these rows are short-lived transport bookkeeping (24 h by default), and a
-- foreign key would only make account deletion a slower, more coupled operation
-- for a cache.
--
-- CreateTable
CREATE TABLE "IdempotencyKey" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "method" TEXT NOT NULL,
    "route" TEXT NOT NULL,
    "requestHash" TEXT NOT NULL,
    "responseStatus" INTEGER,
    "responseBody" JSONB,
    "responseHeaders" JSONB,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "IdempotencyKey_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "IdempotencyKey_expiresAt_idx" ON "IdempotencyKey"("expiresAt");

-- CreateIndex
CREATE UNIQUE INDEX "IdempotencyKey_userId_key_key" ON "IdempotencyKey"("userId", "key");

